            --content-gap: clamp(0.5rem, 1.5vw, 1.5rem);
            --element-gap: clamp(0.25rem, 0.8vw, 0.75rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }
        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }
        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root {
                --title-size: clamp(1.25rem, 7vw, 2.5rem);
            }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           GLOBAL SLIDE STYLES
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* Subtle grid background for all slides */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.015) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.015) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }

        .slide-content {
            position: relative;
            z-index: 1;
        }

        /* Slide number indicator */
        .slide-number {
            position: absolute;
            top: clamp(0.5rem, 2vw, 1.5rem);
            left: clamp(0.5rem, 2vw, 1.5rem);
            font-family: var(--font-display);
            font-size: var(--small-size);
            color: var(--text-muted);
            letter-spacing: 0.15em;
            z-index: 2;
        }

        .slide-tag {
            position: absolute;
            top: clamp(0.5rem, 2vw, 1.5rem);
            right: clamp(0.5rem, 2vw, 1.5rem);
            font-size: var(--label-size);
            color: var(--accent);
            background: var(--accent-dim);
            padding: clamp(0.15rem, 0.4vw, 0.3rem) clamp(0.4rem, 1vw, 0.8rem);
            border-radius: 999px;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            font-weight: 600;
            z-index: 2;
        }

        h2.slide-title {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            line-height: 1.15;
            margin-bottom: var(--content-gap);
            color: var(--text-primary);
        }

        h2.slide-title .accent {
            color: var(--accent);
        }

        h2.slide-title .warm {
            color: var(--accent-warm);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }
        .reveal:nth-child(7) { transition-delay: 0.65s; }
        .reveal:nth-child(8) { transition-delay: 0.75s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity 0.5s var(--ease-out-expo),
                        transform 0.5s var(--ease-out-expo);
        }
        .slide.visible .reveal-scale {
            opacity: 1;
            transform: scale(1);
        }

        /* SVG line chart draw animation */
        .chart-line {
            stroke-dasharray: 2000;
            stroke-dashoffset: 2000;
            transition: stroke-dashoffset 1.5s var(--ease-out-expo);
        }
        .slide.visible .chart-line {
            stroke-dashoffset: 0;
        }
        .chart-line-delay-1 { transition-delay: 0.1s; }
        .chart-line-delay-2 { transition-delay: 0.2s; }
        .chart-line-delay-3 { transition-delay: 0.3s; }
        .chart-line-delay-4 { transition-delay: 0.4s; }
        .chart-line-delay-5 { transition-delay: 0.5s; }
        .chart-line-delay-6 { transition-delay: 0.6s; }
        .chart-line-delay-7 { transition-delay: 0.7s; }
        .chart-line-delay-8 { transition-delay: 0.8s; }
        .chart-line-delay-9 { transition-delay: 0.9s; }

        /* Bar grow animation */
        .bar-fill {
            transform-origin: left center;
            transform: scaleX(0);
            transition: transform 0.8s var(--ease-out-expo);
        }
        .slide.visible .bar-fill {
            transform: scaleX(1);
        }
        .bar-delay-1 { transition-delay: 0.1s; }
        .bar-delay-2 { transition-delay: 0.15s; }
        .bar-delay-3 { transition-delay: 0.2s; }
        .bar-delay-4 { transition-delay: 0.25s; }
        .bar-delay-5 { transition-delay: 0.3s; }
        .bar-delay-6 { transition-delay: 0.35s; }
        .bar-delay-7 { transition-delay: 0.4s; }
        .bar-delay-8 { transition-delay: 0.45s; }
        .bar-delay-9 { transition-delay: 0.5s; }
        .bar-delay-10 { transition-delay: 0.55s; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 100;
            transition: width 0.3s ease;
            box-shadow: 0 0 8px var(--accent);
        }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 1.5vw, 1.2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.6vh, 0.5rem);
            z-index: 100;
        }
        .nav-dot {
            width: clamp(6px, 0.6vw, 8px);
            height: clamp(6px, 0.6vw, 8px);
            border-radius: 50%;
            background: var(--text-muted);
            border: none;
            cursor: pointer;
            transition: all 0.3s ease;
            padding: 0;
        }
        .nav-dot.active {
            background: var(--accent);
            box-shadow: 0 0 6px var(--accent);
            transform: scale(1.3);
        }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        .title-slide {
            background: var(--bg-primary);
            justify-content: center;
            align-items: center;
            text-align: center;
        }
        .title-slide::after {
            content: '';
            position: absolute;
            width: clamp(200px, 40vw, 600px);
            height: clamp(200px, 40vw, 600px);
            border-radius: 50%;
            background: radial-gradient(circle, var(--accent-dim) 0%, transparent 70%);
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            pointer-events: none;
            z-index: 0;
            animation: pulse-glow 4s ease-in-out infinite alternate;
        }
        @keyframes pulse-glow {
            0% { opacity: 0.3; transform: translate(-50%, -50%) scale(0.9); }
            100% { opacity: 0.6; transform: translate(-50%, -50%) scale(1.1); }
        }
        .title-content {
            position: relative;
            z-index: 1;
            max-width: min(85vw, 900px);
        }
        .title-content h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            margin-bottom: clamp(0.5rem, 2vw, 1.5rem);
        }
        .title-content h1 .highlight {
            background: linear-gradient(135deg, var(--accent), #4ea8de);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }
        .title-content .subtitle {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
            max-width: min(80%, 650px);
            margin: 0 auto;
        }
        .title-content .meta-row {
            display: flex;
            justify-content: center;
            gap: clamp(0.8rem, 2vw, 2rem);
            margin-top: clamp(0.8rem, 2vw, 1.5rem);
            flex-wrap: wrap;
        }
        .meta-pill {
            font-size: var(--label-size);
            color: var(--text-secondary);
            background: var(--bg-surface);
            padding: clamp(0.2rem, 0.5vw, 0.4rem) clamp(0.5rem, 1.2vw, 1rem);
            border-radius: 999px;
            border: 1px solid var(--border);
            letter-spacing: 0.04em;
        }
        .meta-pill strong {
            color: var(--accent);
            font-weight: 600;
        }

        /* ===========================================
           SLIDE 2: LINE CHART
           =========================================== */
        .chart-container {
            flex: 1;
            display: flex;
            flex-direction: column;
            min-height: 0;
            max-height: 100%;
        }
        .chart-svg-wrap {
            flex: 1;
            min-height: 0;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .chart-svg-wrap svg {
            width: 100%;
            max-height: min(60vh, 480px);
        }
        .chart-legend {
            display: flex;
            flex-wrap: wrap;
            gap: clamp(0.3rem, 1vw, 0.8rem);
            justify-content: center;
            margin-top: clamp(0.3rem, 1vw, 0.8rem);
        }
        .legend-item {
            display: flex;
            align-items: center;
            gap: clamp(0.2rem, 0.4vw, 0.4rem);
            font-size: var(--label-size);
            color: var(--text-secondary);
        }
        .legend-dot {
            width: clamp(6px, 0.6vw, 10px);
            height: clamp(6px, 0.6vw, 10px);
            border-radius: 50%;
            flex-shrink: 0;
        }
        .trend-callouts {
            display: flex;
            gap: clamp(0.3rem, 1vw, 1rem);
            margin-top: clamp(0.3rem, 0.8vw, 0.6rem);
            flex-wrap: wrap;
        }
        .trend-callout {
            font-size: var(--label-size);
            padding: clamp(0.15rem, 0.4vw, 0.3rem) clamp(0.4rem, 1vw, 0.7rem);
            border-radius: 6px;
            background: var(--bg-surface);
            border: 1px solid var(--border);
        }
        .trend-callout .up { color: var(--accent); }
        .trend-callout .down { color: var(--accent-warm); }

        /* ===========================================
           SLIDES 3 & 4: HORIZONTAL BAR CHARTS
           =========================================== */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.25rem, 0.6vh, 0.5rem);
        }
        .bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.8vw, 0.7rem);
        }
        .bar-label {
            font-size: var(--label-size);
            font-weight: 600;
            color: var(--text-primary);
            min-width: clamp(60px, 8vw, 100px);
            text-align: right;
            flex-shrink: 0;
        }
        .bar-track {
            flex: 1;
            height: clamp(14px, 2vh, 26px);
            background: var(--bg-surface);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }
        .bar-fill {
            height: 100%;
            border-radius: 4px;
            position: relative;
        }
        .bar-value {
            font-size: var(--label-size);
            font-weight: 700;
            color: var(--text-primary);
            min-width: clamp(32px, 4vw, 50px);
            text-align: left;
            flex-shrink: 0;
        }
        .bar-sublabel {
            font-size: var(--label-size);
            color: var(--text-muted);
            margin-left: clamp(0.3rem, 0.8vw, 0.5rem);
        }

        /* Dual bar (primary + adoption) */
        .bar-dual-container {
            display: flex;
            flex-direction: column;
            gap: clamp(0.15rem, 0.3vh, 0.25rem);
        }
        .bar-dual-label-row {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
        }
        .bar-adoption-track {
            height: clamp(6px, 0.8vh, 10px);
            background: var(--bg-surface-alt);
            border-radius: 3px;
            overflow: hidden;
        }
        .bar-adoption-fill {
            height: 100%;
            border-radius: 3px;
            background: var(--accent-blue);
            transform-origin: left center;
            transform: scaleX(0);
            transition: transform 0.8s var(--ease-out-expo);
        }
        .slide.visible .bar-adoption-fill {
            transform: scaleX(1);
        }

        /* ===========================================
           SLIDE 5: DOMAIN HEATMAP
           =========================================== */
        .heatmap-table {
            width: 100%;
            border-collapse: separate;
            border-spacing: clamp(2px, 0.3vw, 4px);
            font-size: var(--label-size);
        }
        .heatmap-table th {
            font-weight: 700;
            color: var(--text-secondary);
            padding: clamp(0.2rem, 0.5vw, 0.4rem) clamp(0.3rem, 0.8vw, 0.6rem);
            text-align: left;
            font-size: var(--label-size);
            letter-spacing: 0.05em;
            text-transform: uppercase;
        }
        .heatmap-table td {
            padding: clamp(0.2rem, 0.5vw, 0.45rem) clamp(0.3rem, 0.8vw, 0.6rem);
            border-radius: 4px;
            font-weight: 500;
        }
        .heatmap-cell-leader {
            font-weight: 700;
        }
        .heatmap-domain {
            color: var(--text-primary);
            font-weight: 600;
            white-space: nowrap;
        }
        .heatmap-lang {
            font-weight: 700;
        }
        .heatmap-pct {
            font-weight: 600;
            font-variant-numeric: tabular-nums;
        }
        .heatmap-py { background: rgba(15, 240, 179, 0.12); color: #0ff0b3; }
        .heatmap-ts { background: rgba(78, 168, 222, 0.12); color: #4ea8de; }
        .heatmap-java { background: rgba(248, 113, 113, 0.12); color: #f87171; }
        .heatmap-cpp { background: rgba(168, 85, 247, 0.12); color: #c084fc; }
        .heatmap-js { background: rgba(251, 191, 36, 0.12); color: #fbbf24; }
        .heatmap-sql { background: rgba(167, 139, 250, 0.12); color: #a78bfa; }

        /* ===========================================
           SLIDE 6: STRATEGIC TAKEAWAYS
           =========================================== */
        .takeaway-list {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1.2vh, 0.9rem);
        }
        .takeaway-item {
            display: flex;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            align-items: flex-start;
            background: var(--bg-surface);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.4rem, 1vw, 0.8rem) clamp(0.5rem, 1.2vw, 1rem);
        }
        .takeaway-item:hover {
            border-color: var(--border-accent);
        }
        .takeaway-num {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 800;
            color: var(--accent);
            line-height: 1;
            flex-shrink: 0;
            min-width: clamp(1.5rem, 2.5vw, 2rem);
        }
        .takeaway-text {
            font-size: var(--body-size);
            color: var(--text-primary);
            line-height: 1.45;
        }
        .takeaway-text .tag {
            display: inline-block;
            font-size: var(--label-size);
            font-weight: 600;
            padding: 0.1em 0.4em;
            border-radius: 3px;
            margin-right: 0.2em;
        }
        .tag-green { background: var(--accent-dim); color: var(--accent); }
        .tag-blue { background: var(--accent-blue-dim); color: var(--accent-blue); }
        .tag-orange { background: var(--accent-warm-dim); color: var(--accent-warm); }

        /* ===========================================
           FOOTER / SOURCE LINE
           =========================================== */
        .source-line {
            position: absolute;
            bottom: clamp(0.4rem, 1vw, 0.8rem);
            left: var(--slide-padding);
            right: var(--slide-padding);
            font-size: var(--label-size);
            color: var(--text-muted);
            display: flex;
            justify-content: space-between;
            z-index: 2;
        }
    </style>
</head>
