    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.isAnimating = false;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupProgressBar();
                this.setupNavDots();
                this.setupWheelNav();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const idx = Array.from(this.slides).indexOf(entry.target);
                            if (idx !== -1) {
                                this.currentSlide = idx;
                                this.updateProgressBar();
                                this.updateNavDots();
                            }
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    } else if (e.key === 'Home') {
                        e.preventDefault();
                        this.goToSlide(0);
                    } else if (e.key === 'End') {
                        e.preventDefault();
                        this.goToSlide(this.slides.length - 1);
                    }
                });
            }

            setupTouchNav() {
                let touchStartY = 0;
                document.addEventListener('touchstart', (e) => {
                    touchStartY = e.touches[0].clientY;
                }, { passive: true });
                document.addEventListener('touchend', (e) => {
                    const diff = touchStartY - e.changedTouches[0].clientY;
                    if (Math.abs(diff) > 50) {
                        if (diff > 0) this.goToSlide(this.currentSlide + 1);
                        else this.goToSlide(this.currentSlide - 1);
                    }
                }, { passive: true });
            }

            setupWheelNav() {
                let wheelTimeout = null;
                let lastWheelTime = 0;
                document.addEventListener('wheel', (e) => {
                    e.preventDefault();
                    const now = Date.now();
                    if (now - lastWheelTime < 800) return;
                    lastWheelTime = now;
                    if (e.deltaY > 0) this.goToSlide(this.currentSlide + 1);
                    else if (e.deltaY < 0) this.goToSlide(this.currentSlide - 1);
                }, { passive: false });
            }

            setupProgressBar() {
                this.progressBar = document.getElementById('progressBar');
                this.updateProgressBar();
            }

            updateProgressBar() {
                if (!this.progressBar) return;
                const pct = ((this.currentSlide + 1) / this.slides.length) * 100;
                this.progressBar.style.width = pct + '%';
            }

            setupNavDots() {
                const navContainer = document.getElementById('navDots');
                if (!navContainer) return;
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('button');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
                    dot.addEventListener('click', () => this.goToSlide(i));
                    navContainer.appendChild(dot);
                });
            }

            updateNavDots() {
                const dots = document.querySelectorAll('.nav-dot');
                dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === this.currentSlide);
                });
            }

            goToSlide(index) {
                if (index < 0 || index >= this.slides.length) return;
                this.currentSlide = index;
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
                this.updateProgressBar();
                this.updateNavDots();
            }
        }

        new SlidePresentation();
    </script>
</body>
